/* ===== module: sync-auth.js ===== */
    /** Auth: session lifecycle, sign-in code, profile updates, sign out, the
     *  login-transition adopt/upload step, and resume/init (split from sync.js, #99 B15).
     *
     *  - Login paradigm (user 2026-09-11): the login TRANSITION is
     *    adopt-vs-upload, never a merge. Remote has data (existing account)
     *    → discard local syncable state and adopt the cloud wholesale.
     *    Remote empty (new account) → upload local (keep it). This runs once
     *    per uid, gated on a persisted adopted-uid marker so reloads,
     *    back-online resumes, and visibility changes never re-trigger it.
     *  - A17: handleAuthChange refreshes lastAuthProfile from the live
     *    session's user_metadata — it no longer resets the profile, so the
     *    display name and account type persist in memory across auth changes.
     *  - window.lastAuthUid mirrors Sync.lastAuthUid as the deliberate
     *    cross-file auth hint read by share.js (its #207 mint gate);
     *    Sync.lastAuthEmail is the email equivalent used by email-sync.js.
     */
     /* Module map (v1.006) — Key: initSync(), sendSignInLink(), verifySignInCode(), signOutAccount(), adoptOrUploadOnSignIn(), handleAuthChange(). Depends on: sync-adapter (session/client), sync-engine (merge/push), persistence (syncable keys). */
    /* #99 C4: IIFE + shared Sync namespace — the pattern is explained at sync-adapter.js:11. */
    var Sync = window.Sync = window.Sync || {};
    (function(){
      'use strict';
      /* Login-transition marker (user 2026-09-11): the adopt-vs-upload decision
         must run exactly once per account sign-in, never on reload/online/
         visibility resume (resumeSync calls handleAuthChange on all of those —
         wiping there would destroy offline edits). Set when the transition
         settles for a uid; cleared on sign-out and account deletion. */
      const ADOPTED_UID_KEY='workout-app:adopted-uid';
      /* Reads the adopted-account uid from localStorage. */
      function getAdoptedUid(){try{return localStorage.getItem(ADOPTED_UID_KEY)||null;}catch(_){return null;}}
      /* Stores the adopted-account uid in localStorage. */
      function setAdoptedUid(uid){try{localStorage.setItem(ADOPTED_UID_KEY,uid);}catch(_){}}
      /* Clears the adopted-account uid. */
      function clearAdoptedUid(){try{localStorage.removeItem(ADOPTED_UID_KEY);}catch(_){}}
      /* #453 (2026-09-14): wait for the login transition to settle before
         closing a sign-in dialog into the app. The silent adopt on an empty
         device finishes a beat after verifyOtp resolves — the adopted-uid
         marker lands only after the adopt (or the #288 choice) is fully
         settled. Resolves true when the marker matches uid, false on timeout
         (the auth handler's own re-render still covers that path). */
      async function waitForLoginSettled(uid,timeoutMs){
        if(!uid)return false;
        const budget=typeof timeoutMs==='number'&&timeoutMs>0?timeoutMs:10000;
        const t0=Date.now();
        while(Date.now()-t0<budget){
          if(getAdoptedUid()===uid)return true;
          await new Promise(r=>setTimeout(r,150));
        }
        return getAdoptedUid()===uid;
      }
      let syncInitialized=false, authListenerAttached=false;

      /* ===== identity state =====
         Sync.lastAuthUid is the source of truth; the bare global `lastAuthUid`
         is kept in sync for pre-existing callers (share.js). */
      Sync.lastAuthUid=Sync.lastAuthUid||null;
      Sync.lastAuthEmail=Sync.lastAuthEmail||'';
      /* Keep the bare global in sync from load for pre-existing readers (share.js). */
      try{if(window.lastAuthUid===undefined)window.lastAuthUid=null;}catch(_){}
      /* Account profile (2026-09-10, #30): display name + account_type live in
         Supabase user_metadata so they sync across devices with the session. */
      Sync.lastAuthProfile=Sync.lastAuthProfile||{display_name:'',account_type:'free'};
      /* Records the signed-in uid/email on the Sync namespace (and window shim). */
      function setAuthIdentity(uid,email){
        Sync.lastAuthUid=uid;
        Sync.lastAuthEmail=email||'';
        try{window.lastAuthUid=uid;}catch(_){} /* global shim for share.js */
      }
      /* ===== sign-in code =====
         #215: the Supabase sign-in actions, parameterized so the Settings
         account card and the share sign-in modal reuse the same logic with
         their own inputs and status writers. Both return true on success. */
      async function requestSignInCode(opts){
        const email=(opts&&opts.email||'').trim();
        const setStatus=(opts&&opts.setStatus)||Sync.setAccountStatus;
        if(!email||email.indexOf('@')<0){setStatus('Enter a valid email address.',true);return false;}
        const left=Sync.magicLinkCooldownRemaining();
        if(left>0){setStatus('Wait '+Math.ceil(left/1000)+'s before requesting another link.',true);return false;}
        /* #427 (user 2026-09-13): a single failed Supabase CDN import latched
           supabaseUnavailable, so every later tap reported "can't reach the
           network" on a healthy connection. An explicit sign-in tap always
           retries the import; boot-time callers keep the latch. */
        try{if(Sync.resetSupabaseUnavailable)Sync.resetSupabaseUnavailable();}catch(_){}
        const sb=await Sync.getSupabase();
        if(!sb){setStatus('Can\u2019t reach the network \u2014 try again when you\u2019re online.',true);return false;}
        setStatus('Sending code\u2026');
        try{
          const {error}=await sb.auth.signInWithOtp({email:email,options:{emailRedirectTo:location.origin+location.pathname}});
          /* Cooldown starts on any completed attempt — even a rate-limited one —
             so rapid taps can't burn the Supabase email quota. A network
             failure never reached the server, so it must not start the
             cooldown (#427: resend has to work immediately after a network
             error). */
          if(!authNetworkError(error))Sync.startMagicLinkCooldown();
          if(error){setStatus(sendLinkErrorText(error),true);return false;}
          return true;
        }catch(err){setStatus(requestErrorText(err,'Could not send the code.'),true);return false;}
      }
      /* #427: the Settings "Resend code" button in the sign-in error state. */
      function setResendVisible(visible){
        try{const b=$('#resendCodeButton');if(b)b.hidden=!visible;}catch(_){}
      }
      /* Sends the sign-in code from the Settings card and reveals the OTP step. */
      async function sendSignInLink(){
        /* Settings wrapper: same logic, plus the card's progressive disclosure. */
        setResendVisible(false);
        const input=$('#accountEmail');
        const email=(input&&input.value||'').trim();
        const ok=await requestSignInCode({email,setStatus:Sync.setAccountStatus});
        /* Nitpick R-31: Resend is the retry for an attempted send
           (#427) — a validation failure (no valid email entered) never
           sent anything, so it must not reveal the Resend button. */
        if(!ok){if(email&&email.indexOf('@')>=0)setResendVisible(true);return;}
        /* #75: progressive disclosure — reveal the code step once the email is sent. */
        const otpStep=$('#otpStep');
        if(otpStep)otpStep.hidden=false;
        /* #124 (user 2026-09-11): after sending, the status says only this — the
           OTP field sits directly above the status line, and the code-first
           flow is primary (#75). */
        Sync.setAccountStatus('Code sent, enter it above.');
      }
      /* ===== 6-digit sign-in code (2026-09-11) =====
         verifyOtp needs no PKCE code verifier, so it completes wherever the
         email is read — including the iPhone home-screen app, whose storage
         is isolated from Safari and which never sees a tapped magic link. */
      async function confirmSignInCode(opts){
        const email=(opts&&opts.email||'').trim();
        const token=(opts&&opts.token||'').trim().replace(/[\s-]+/g,'');
        const setStatus=(opts&&opts.setStatus)||Sync.setAccountStatus;
        if(!email||email.indexOf('@')<0){setStatus('Enter your email address above first.',true);return false;}
        if(!token){setStatus('Enter the code from the email.',true);return false;}
        /* #427: same import-retry as requestSignInCode — a latched CDN
           failure must not masquerade as "can't reach the network" here. */
        try{if(Sync.resetSupabaseUnavailable)Sync.resetSupabaseUnavailable();}catch(_){}
        const sb=await Sync.getSupabase();
        if(!sb){setStatus('Can\u2019t reach the network \u2014 try again when you\u2019re online.',true);return false;}
        setStatus('Verifying code\u2026');
        try{
          const {error}=await sb.auth.verifyOtp({email:email,token:token,type:'email'});
          if(error){setStatus(otpErrorText(error),true);return false;}
          /* onAuthStateChange -> handleAuthChange picks up the session and
             runs the first sync cycle. */
          setStatus('');
          return true;
        }catch(err){setStatus(requestErrorText(err,'Could not verify the code.'),true);return false;}
      }
      /* Verifies the sign-in code from the Settings card's inputs. */
      async function verifySignInCode(){
        /* Settings wrapper: same logic, reading the card's inputs. */
        setResendVisible(false);
        const emailInput=$('#accountEmail');
        const input=$('#accountOtp');
        const ok=await confirmSignInCode({email:(emailInput&&emailInput.value||''),token:(input&&input.value||''),setStatus:Sync.setAccountStatus});
        if(!ok){setResendVisible(true);return;}
        if(ok&&input)input.value='';
      }
      /* Friendlier wording for "Email me a code" send failures (#70).
         Network-type failures must never surface raw ("Load failed"): the
         request can fail as a RETURNED error or a throw, so both text fns
         translate. The local regex is a backstop in case the adapter module
         didn't load. */
      function authNetworkError(err){
        try{if(Sync.isNetworkError&&Sync.isNetworkError(err))return true;}catch(_){}
        const m=String((err&&(err.message||err))||'').toLowerCase();
        return /load failed|failed to fetch|network error|network request failed|fetch failed|econn|etimedout|enotfound|socket|offline/.test(m);
      }
      const AUTH_NETWORK_MSG='Can\u2019t reach the network \u2014 check your connection and try again.';
      /* User-facing message for a failed sign-in code send. */
      function sendLinkErrorText(error){
        if(authNetworkError(error))return AUTH_NETWORK_MSG;
        const msg=String((error&&error.message)||'');
        const low=msg.toLowerCase();
        if(low.indexOf('rate limit')>=0||low.indexOf('too many')>=0||/after \d+ second/.test(low))
          return 'Too many requests \u2014 wait a moment, then tap \u2018Email me a code\u2019 again.';
        if(low.indexOf('error sending')>=0||low.indexOf('could not send')>=0)
          return 'Couldn\u2019t send the email \u2014 double-check the address and try again.';
        return msg||'Could not send the code.';
      }
      /* Friendlier wording for the common code failures (#70: cryptic errors). */
      function otpErrorText(error){
        if(authNetworkError(error))return AUTH_NETWORK_MSG;
        const msg=String((error&&error.message)||'');
        const low=msg.toLowerCase();
        if(low.indexOf('expired')>=0)return 'That code expired \u2014 tap \u2018Send a code\u2019 for a fresh one.'; /* #525: names the resend button's new label */
        if(low.indexOf('invalid')>=0||low.indexOf('used')>=0||low.indexOf('token')>=0)return 'That code didn\u2019t work \u2014 double-check it against the email and try again.';
        return msg||'Could not verify the code.';
      }
      /* User-facing message for a failed sign-in request, network wording first. */
      function requestErrorText(err,fallback){
        if(authNetworkError(err))return AUTH_NETWORK_MSG;
        return (err&&err.message)||fallback;
      }
      /* ===== profile / sign out ===== */
      async function saveDisplayName(){
        const sb=await Sync.getSupabase();
        if(!sb){Sync.setAccountStatus('Can\u2019t reach the network \u2014 try again when you\u2019re online.',true);return;}
        const value=(($('#editNameInput')&&$('#editNameInput').value)||'').trim().slice(0,60);
        try{
          const {error}=await sb.auth.updateUser({data:{display_name:value}});
          if(error){Sync.setAccountStatus(error.message,true);return;}
        }catch(err){Sync.setAccountStatus((err&&err.message)||'Could not save the name.',true);return;}
        Sync.lastAuthProfile.display_name=value;
        const d=$('#editNameDialog');if(d)d.close();
        Sync.setAccountStatus('');
        Sync.renderAccount();
      }
      /* #423 (user 2026-09-13): change the sign-in email via the standard
         Supabase email-change flow — updateUser({email}) sends a
         confirmation link to the NEW address and the change completes when
         it is tapped. The local lastAuthEmail stays as-is until the auth
         state actually changes on a later session. */
      function isValidEmailAddress(v){return typeof v==='string'&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);}
      /* Changes the account email (Supabase update + confirmation email). */
      async function saveAccountEmail(){
        const sb=await Sync.getSupabase();
        if(!sb){Sync.setAccountStatus('Can\u2019t reach the network \u2014 try again when you\u2019re online.',true);return;}
        const value=(($('#editEmailInput')&&$('#editEmailInput').value)||'').trim();
        if(!isValidEmailAddress(value)){Sync.setAccountStatus('Enter a valid email address.',true);return;}
        if(value.toLowerCase()===(Sync.lastAuthEmail||'').toLowerCase()){Sync.setAccountStatus('That\u2019s already your sign-in email.',true);return;}
        try{
          const {error}=await sb.auth.updateUser({email:value});
          if(error){Sync.setAccountStatus(error.message,true);return;}
        }catch(err){Sync.setAccountStatus((err&&err.message)||'Could not change the email.',true);return;}
        const d=$('#editEmailDialog');if(d)d.close();
        Sync.renderAccount();
        Sync.setAccountStatus('Confirmation sent to '+value+' \u2014 tap the link there to complete the change.');
      }
      /* Best-effort push of dirty keys, then signs out and clears local auth state. */
      async function signOutAccount(){
        /* Persona-5 finding 3: offline edits that never reached the cloud were
           destroyed with no push attempt. Best-effort push BEFORE the local
           sign-out kills the session (pushDirtyKeys needs the session) —
           raced against a short timeout so a dead network can't hang
           sign-out. On failure we proceed with the wipe; the dialog already
           warns that unpushed data can't be recovered. */
        try{
          if(typeof Sync.pushDirtyKeys==='function'){
            await Promise.race([
              Sync.pushDirtyKeys(),
              new Promise(function(res){setTimeout(res,8000);})
            ]);
          }
        }catch(_){}
        const sb=await Sync.getSupabase();
        /* #305 (user 2026-09-13): the local session must die even when the
           network is down. The default global signOut() calls /auth/v1/logout
           first — a failed call left the sb-*-auth-token session key in place,
           and after the reload the live session silently re-adopted the whole
           cloud copy, so the wipe appeared to do nothing. scope:'local'
           clears the session from storage with no network call at all; the
           server-side revocation is irrelevant to wiping this device. */
        try{if(sb)await sb.auth.signOut({scope:'local'});}catch(_){}
        setAuthIdentity(null,'');
        Sync.lastAuthProfile={display_name:'',account_type:'free'};
        /* #465 (user 2026-09-14): a fresh sign-in after sign-out must always
           show the sign-in button — lift any magic-link resend cooldown so a
           stale key can't hijack it. */
        if(typeof Sync.clearMagicLinkCooldown==='function')Sync.clearMagicLinkCooldown();
        /* The next sign-in for any account re-runs the adopt-vs-upload
           transition (the adopted marker must not survive sign-out). */
        clearAdoptedUid();
        /* User 2026-09-12 (major bug): signing out actually signs out — the
           device is wiped clean of workout data instead of keeping it. The
           cloud copy re-adopts on the next sign-in, so nothing is lost.
           Persona QA 2026-09-16: await the wipe's IndexedDB delete so the
           reload below can't resurrect the blob. */
        if(typeof wipeLocalUserData==='function'){try{await wipeLocalUserData({removeSyncKeys:true});}catch(_){}}
        if(Sync.resetSyncMeta)Sync.resetSyncMeta();
        Sync.setAccountStatus('Signed out.');
        Sync.renderAccount();
        /* A share preview paints before auth resolves — let it re-render so
           the primary action matches the account state (user 2026-09-12). */
        if(typeof noteShareAuthChanged==='function'){try{noteShareAuthChanged();}catch(_){}}
        /* Reload into the clean, signed-out state (mirrors delete-account). */
        setTimeout(()=>location.reload(),1200);
      }
      /* Manual "Sync now" from the account screen, with status feedback. */
      async function syncNowManual(){
        Sync.setAccountStatus('Syncing\u2026');
        const ok=await Sync.syncCycle({manual:true}); /* #412: a tapped Sync now always gets feedback */
        if(ok){
          Sync.setAccountStatus('');
          /* The pull already toasted a non-empty merge; a quiet cycle still
             deserves an answer to the tap. */
          const r=Sync.lastMergeReport?Sync.lastMergeReport():null;
          const total=r?(r.added||0)+(r.updated||0)+(r.removed||0):0;
          if(!total)Sync.syncToast('Up to date.');
        }
        else Sync.setAccountStatus('Sync unavailable \u2014 sign in and check your connection.',true);
        Sync.renderAccount();
      }
      /* ===== login-transition adopt-vs-upload (user 2026-09-11) ===== */
      /* #288 (user 2026-09-13): when BOTH sides hold data, sign-in asks instead
         of silently discarding local state. Resolves 'both'|'cloud'|'device'.
         #415 follow-up (user 2026-09-13): "Not now" is gone — this is a forced
         choice between the three data options; Esc is blocked so the dialog
         can only settle on a real pick (or a showModal failure, which wipes
         nothing and retries on a later sign-in). */
      let signInChoiceResolver=null,signInChoiceWired=false;
      /* #286 follow-up (user 2026-09-13): the post-workout nudge offers "Keep
         the workout I just finished" — this id survives even the "Use cloud
         data" choice, which otherwise discards all local state. */
      Sync.pendingKeepWorkoutId=null;
      /* Wires the sign-in choice dialog buttons (one-time). */
      function wireSignInChoice(){
        if(signInChoiceWired)return;signInChoiceWired=true;
        const done=choice=>{
          try{$('#signInChoiceDialog').close();}catch(_){}
          const r=signInChoiceResolver;signInChoiceResolver=null;
          if(r)r(choice);
        };
        document.querySelectorAll('[data-signin-choice]').forEach(b=>b.addEventListener('click',()=>done(b.dataset.signinChoice)));
        /* #415 follow-up (user 2026-09-13): "Use this device" overwrites the
           account's data — show the "are you sure" confirmation screen first.
           The confirm screen's own data-signin-choice buttons are already
           wired above; Back returns to the main choice view. */
        $('#signInChoiceDeviceBtn')?.addEventListener('click',()=>{
          $('#signInChoiceMain').hidden=true;
          $('#signInChoiceConfirm').hidden=false;
        });
        $('#signInChoiceBack')?.addEventListener('click',()=>{
          $('#signInChoiceConfirm').hidden=true;
          $('#signInChoiceMain').hidden=false;
        });
        /* Esc is blocked — the choice is forced, never silently dismissed. */
        $('#signInChoiceDialog')?.addEventListener('cancel',e=>{e.preventDefault();});
        $('#signInChoiceDialog')?.addEventListener('close',()=>{if(signInChoiceResolver)done(null);});
      }
      /* #415/#424 (user 2026-09-13): the RECOMMENDED badge follows
         account-data logic, not a hardcoded default. Full account (5+
         substantive items, has saved workouts) → recommend "Use account
         data". Minimal account (<5 items) or an account with no saved
         workouts → recommend "Keep both". No saved workouts → the cloud
         option is hidden entirely (adopting it could only destroy the
         device's templates — there is no template-side gain). "Use this
         device" is NEVER recommended. */
      const ACCOUNT_MINIMAL_THRESHOLD=5;
      /* Counts of real local data (logs, templates, programs, customs) used to
         recommend a sign-in choice. */
      function accountSubstance(byKey){
        const val=k=>{try{const r=byKey[k];return (r&&'value' in r)?r.value:null;}catch(_){return null;}};
        const arr=k=>{const v=val(k);return Array.isArray(v)?v:[];};
        const logs=arr('completed').length;
        /* parity with isEmptySyncValue: built-in templates don't count */
        const saved=arr('templates').filter(t=>t&&!t.builtIn).length;
        const ap=val('activeProgram');
        const programs=((ap&&typeof ap==='object'&&Object.keys(ap).length)?1:0)
          +arr('savedPrograms').length+arr('archivedPrograms').length;
        const customs=arr('customExercises').length;
        return {logs,saved,programs,customs,total:logs+saved+programs+customs};
      }
      /* Set by adoptOrUploadOnSignIn before askSignInChoice() opens the
         dialog; the renderer below positions RECOMMENDED per the table. */
      let signInChoiceSubstance=null;
      /* #424 (user 2026-09-13): the RECOMMENDED badge decision, extracted
         as a named pure function for unit tests. 'device' is never a valid
         recommendation — the badge only ever lands on 'cloud' or 'both'. */
      function recommendSignInChoice(substance){
        const s=substance||{saved:1,total:ACCOUNT_MINIMAL_THRESHOLD};
        if(s.saved===0)return 'both'; /* cloud hidden: nothing to adopt */
        return s.total>=ACCOUNT_MINIMAL_THRESHOLD?'cloud':'both';
      }
      /* Paints the sign-in choice dialog, badge-highlighting the recommended option. */
      function renderSignInChoiceForSubstance(){
        const substance=signInChoiceSubstance||{saved:1,total:ACCOUNT_MINIMAL_THRESHOLD};
        const hideCloud=substance.saved===0;
        const targetKey=recommendSignInChoice(substance);
        ['#signInChoiceMain','#signInChoiceConfirm'].forEach(viewSel=>{
          const view=document.querySelector(viewSel);if(!view)return;
          view.querySelectorAll('.choice-option').forEach(opt=>{
            opt.classList.remove('choice-recommended');
            const badge=opt.querySelector('.recommended-badge');
            if(badge)badge.remove();
            if(opt.dataset&&opt.dataset.signinChoice==='cloud')opt.hidden=hideCloud;
            if(opt.dataset&&opt.dataset.signinChoice===targetKey){
              opt.classList.add('choice-recommended');
              const strong=opt.querySelector('strong');
              if(strong&&!strong.querySelector('.recommended-badge')){
                const b=document.createElement('span');
                b.className='recommended-badge';b.textContent='Recommended';b.style.setProperty('color','#fff','important');
                strong.appendChild(b);
              }
            }
          });
          /* No dangling "or" when the cloud option is hidden. */
          view.querySelectorAll('.choice-or').forEach(el=>{el.hidden=hideCloud;});
        });
      }
      /* Opens the sign-in choice dialog; resolves with the user's pick or null. */
      function askSignInChoice(){
        wireSignInChoice();
        return new Promise(resolve=>{
          signInChoiceResolver=resolve;
          const dlg=$('#signInChoiceDialog');
          /* #415: always open on the main choice view — the confirm view may
             still be showing from a previous attempt. */
          try{$('#signInChoiceMain').hidden=false;$('#signInChoiceConfirm').hidden=true;}catch(_){}
          renderSignInChoiceForSubstance();
          if(dlg&&typeof dlg.showModal==='function'){try{dlg.showModal();}catch(_){resolve(null);}}
          else resolve(null);
        });
      }
      /* #450 (user 2026-09-14): seed defaults are not user data. A device that
         holds ONLY the seeded tag lists (tags / exerciseTagPresets default to
         8 items each at boot) has no local data worth choosing about — sign-in
         must skip the "What should we keep?" dialog and adopt the account
         silently. Deliberately stricter than isEmptySyncValue: a lone default
         tag still counts as "data" for the merge guards (sync-merge.test.js),
         but for the sign-in transition seed-only arrays are empty. */
      function signInValueHasUserData(key,value){
        if(Sync.isEmptySyncValue(key,value))return false;
        if(Array.isArray(value)){
          if(key==='tags'&&typeof DEFAULT_SET_TAGS!=='undefined')
            return value.some(t=>!DEFAULT_SET_TAGS.includes(t));
          if(key==='exerciseTagPresets'&&typeof DEFAULT_EXERCISE_TAG_PRESETS!=='undefined')
            return value.some(t=>!DEFAULT_EXERCISE_TAG_PRESETS.includes(t));
        }
        return true;
      }
      /* True when any of the given syncable keys holds user data. */
      function signInLocalHasData(dataKeys){
        return dataKeys.some(k=>{try{return signInValueHasUserData(k,getSyncableValue(k));}catch(_){return false;}});
      }
      /** Login transition: remote has data (existing account) →
          - local empty: adopt the cloud wholesale (no merge);
          - local ALSO has data (#288): ask — keep both (merge), use cloud
            (discard local), or use this device (local wins);
          remote empty (new account) → upload local (keep it).
          Returns true when the transition settled; false on offline/fetch
          error or dismissal — the caller then wipes NOTHING and leaves the
          adopted marker unset so a later sign-in retries. Never wipe on
          uncertain state. */
      async function adoptOrUploadOnSignIn(user){
        Sync.ensureSyncMeta();
        const sb=await Sync.getSupabase();
        if(!sb||!navigator.onLine)return false;
        /* #422 (user 2026-09-13): first-time signup must never see the
           "What should we keep?" dialog — a just-created account takes the
           same path as the remote-empty branch below. 1-minute freshness
           window on the auth user's created_at; returning sign-ins keep the
           exact current behavior. Guarded so a missing/unparseable created_at
           falls back to current behavior — never crash, never wipe. */
        let accountFresh=false;
        try{
          const createdMs=Date.parse(user&&user.created_at);
          accountFresh=Number.isFinite(createdMs)&&(Date.now()-createdMs)<60*1000;
        }catch(_){accountFresh=false;}
        if(accountFresh){
          const ok=await Sync.syncCycle();
          if(ok)Sync.setAccountStatus('Signed in \u2014 your data was saved to your account.');
          return ok;
        }
        let rows;
        try{
          const res=await sb.from('user_data').select('key,value,updated_at').eq('user_id',user.id);
          if(res.error){Sync.showSyncError(res.error);return false;}
          rows=res.data;
        }catch(err){Sync.showSyncError(err);return false;}
        const byKey={};
        (rows||[]).forEach(r=>{if(r&&typeof r.key==='string')byKey[r.key]=r;});
        /* #415/#424: measure the account once — the recommendation logic and
           the cloud-option visibility rule below use this, no extra query. */
        const substance=accountSubstance(byKey);
        /* A1 (#99): only data-bearing keys count — UI prefs never make an
           account "non-empty". */
        const dataKeys=(typeof DATA_SYNC_KEYS!=='undefined')?DATA_SYNC_KEYS:SYNCABLE_KEYS;
        const remoteHasData=dataKeys.some(k=>byKey[k]&&!Sync.isEmptySyncValue(k,byKey[k].value));
        /* #415/#424: an account with zero substantive items is an empty
           account even if it holds prefs-only rows — take the upload path,
           never the dialog. */
        if(!remoteHasData||substance.total===0){
          /* New account: upload local (keep it) — the existing first-sign-in
             migration path. */
          const ok=await Sync.syncCycle();
          if(ok)Sync.setAccountStatus('Signed in \u2014 your data was saved to your account.');
          return ok;
        }
        /* A1 companion: check the live value, not the snapshot (snapshots are
           hashes now — see sync-engine.js).
           #450 (user 2026-09-14): seed-only devices count as empty — sign-in
           skips the "What should we keep?" dialog and adopts the account. */
        const localHasData=signInLocalHasData(dataKeys);
        if(localHasData){
          /* #288: both sides hold data — the user picks, nothing is silently
             discarded. */
          /* #286 follow-up: when the post-workout nudge's "keep" option is on,
             say so on the cloud option — its copy otherwise promises to
             discard everything on the device. */
          const cloudOpt=document.querySelector('#signInChoiceDialog [data-signin-choice="cloud"] .choice-desc');
          const origCloudCopy=cloudOpt?cloudOpt.textContent:null;
          if(Sync.pendingKeepWorkoutId&&cloudOpt)cloudOpt.textContent+=' The workout you just finished is kept regardless.';
          signInChoiceSubstance=substance;
          const choice=await askSignInChoice();
          signInChoiceSubstance=null;
          if(cloudOpt&&origCloudCopy!==null)cloudOpt.textContent=origCloudCopy;
          if(choice==='both'){
            const ok=await Sync.syncCycle();
            if(ok)Sync.setAccountStatus('Signed in \u2014 merged this device with your account.');
            return ok;
          }
          if(choice==='device'){
            /* #645: "Use this device" is the overwrite the dialog promises
               ("Anything on your account that isn't on this device will be
               lost"). The old body only re-stamped via markSyncDirty — a
               no-op for already-snapshotted data — and then merged, so it
               silently behaved exactly like "Keep both": cloud-only items
               unioned back in and newer remote scalars won. Now:
               (a) every revisioned item on this device is stamped at now,
               so per-item LWW favors the device's copies of shared items;
               (b) cloud-only collection items are tombstoned — registry
               tombstones for completed/templates/archivedPrograms/
               savedPrograms (#646 gave savedPrograms the channel),
               in-array stubs for customExercises (its native channel) —
               so the cycle's merge cannot resurrect them;
               (c) every data key gets a fresh key stamp + the dirty latch
               (possessed asserted by the user's explicit choice), so
               whole-key LWW keeps local scalars and empty local keys push
               empty instead of adopting the account's copy.
               String-list keys (tags/exerciseTagPresets/favorites) keep
               union semantics — the engine has no delete channel for bare
               strings; the dialog's substance (workouts, programs,
               templates, customs) is what overwrites. */
            const nowMs=Date.now(), nowIso=new Date(nowMs).toISOString();
            for(const key of dataKeys){
              const local=getSyncableValue(key);
              if(Array.isArray(local))for(const it of local){
                if(it&&typeof it==='object'&&it.id!=null&&!Sync.isTombstoned(it)){try{it.updatedAt=nowMs;}catch(_){}}
              }
            }
            for(const key of dataKeys){
              const remote=byKey[key], local=getSyncableValue(key);
              if(!remote||!Array.isArray(remote.value)||!Array.isArray(local))continue;
              const localIds=new Set();
              for(const it of local)if(it&&typeof it==='object'&&it.id!=null)localIds.add(String(it.id));
              let stubbed=false;
              for(const rItem of remote.value){
                if(!rItem||typeof rItem!=='object'||rItem.id==null||Sync.isTombstoned(rItem))continue;
                if(localIds.has(String(rItem.id)))continue;
                Sync.noteTombstone(key,rItem.id);
                if(key==='customExercises'){local.push({id:rItem.id,deletedAt:nowMs});stubbed=true;}
              }
              if(stubbed)setSyncableValue(key,local);
            }
            Sync.markSyncDirty();
            const meta=Sync.getSyncMeta();
            for(const key of dataKeys){
              const m=meta.keys[key];
              if(m){
                m.updatedAt=nowIso;m.dirty=true;m.possessed=true;
                /* #782 A1: scalar keys have no tombstone channel — for an
                   empty local scalar (no program, no favorite stamps) the
                   explicit choice itself is the delete evidence, stamped
                   so the engine's empty-push guard lets the overwrite
                   through instead of reading the empty as an unexplained
                   absence and adopting the account's copy back. */
                if((key==='activeProgram'||key==='favoriteStamps')&&Sync.isEmptySyncValue(key,getSyncableValue(key)))m.deliberateEmpty=true;
              }
            }
            Sync.saveSyncMeta();
            persistNow();
            const ok=await Sync.syncCycle();
            if(ok)Sync.setAccountStatus('Signed in \u2014 your device\u2019s data was saved to your account.');
            return ok;
          }
          /* Unsettled (showModal unavailable — the only path to null now that
             "Not now" is gone and Esc is blocked): wipe nothing, retry on a
             later sign-in. */
          if(choice!=='cloud')return false;
        }
        /* Existing account: discard local syncable state, adopt remote
           wholesale. Keys with no remote row are cleared locally so stale
           device state can't resurrect on the next push. Tombstones clear too —
           the cloud is authoritative for this account. */
        Sync.clearTombstoneRegistry();
        /* #286 follow-up: capture the to-keep workout from the pre-discard
           local snapshot — it is re-appended after the remote is adopted. */
        let keepWorkout=null;
        if(Sync.pendingKeepWorkoutId){
          /* Read the live value — snapshots are hashes now. */
          try{
            const local=getSyncableValue('completed');
            if(Array.isArray(local))keepWorkout=local.find(w=>w&&w.id===Sync.pendingKeepWorkoutId)||null;
          }catch(_){keepWorkout=null;}
        }
        const meta=Sync.getSyncMeta();
        for(const key of SYNCABLE_KEYS){
          const remote=byKey[key];
          if(remote)Sync.applyRemoteKey(key,remote);
          else{
            Sync.clearSyncableKey(key);
            meta.keys[key]={updatedAt:new Date(0).toISOString(),snapshot:Sync.snapshotOf(key),dirty:false};
          }
        }
        if(typeof mergeCustomExercises==='function'){try{mergeCustomExercises();}catch(_){}}
        Sync.saveSyncMeta();
        persistNow();
        if(keepWorkout){
          /* Re-append the just-finished workout (dedupe by id) and push it up —
             the cloud choice no longer loses it. */
          const arr=getSyncableValue('completed');
          if(Array.isArray(arr)&&!arr.some(w=>w&&w.id===keepWorkout.id)){
            arr.unshift(keepWorkout);
            setSyncableValue('completed',arr);
            Sync.markSyncDirty();
            persistNow();
          }
        }
        Sync.pendingKeepWorkoutId=null;
        /* #415 "workout not found": the cloud branch wiped local templates —
           a dangling savedWorkoutId would re-render "Saved workout not
           found". Sanitize before the re-render; the list view is the
           fallback. */
        try{
          const ids=new Set((workoutState.templates||[]).map(t=>t&&t.id));
          if(state.savedWorkoutId&&!ids.has(state.savedWorkoutId))state.savedWorkoutId=null;
        }catch(_){}
        Sync.rerenderCurrentView();
        meta.everSynced=true;
        Sync.saveSyncMeta();
        Sync.setAccountStatus(keepWorkout?'Signed in \u2014 loaded your account data. The workout you just finished was kept and will sync up.':'Signed in \u2014 loaded your account data. Anything previously on this device was replaced.');
        return true;
      }
      /* Supabase auth callback: adopts/uploads on first sign-in per uid, resumes
         sync otherwise. */
      async function handleAuthChange(session){
        const user=session&&session.user?session.user:null;
        const uid=user?user.id:null;
        const meta=(user&&user.user_metadata)||{};
        /* A17: refresh the profile from the live session's user_metadata —
           the display name and account type persist in memory across auth
           changes instead of being reset. */
        Sync.lastAuthProfile={display_name:meta.display_name||'',account_type:meta.account_type||'free'};
        /* Seed account_type=free once so the structure exists from the start;
           nothing about pricing changes — everything stays free. */
        if(user&&!meta.account_type){
          try{const sb=await Sync.getSupabase();if(sb)await sb.auth.updateUser({data:{account_type:'free'}});}catch(_){}
        }
        if(uid===Sync.lastAuthUid&&syncInitialized){Sync.renderAccount();return;}
        setAuthIdentity(uid,user?(user.email||''):'');
        /* A share preview paints before auth resolves — let it re-render so
           the primary action matches the account state (user 2026-09-12). */
        if(typeof noteShareAuthChanged==='function'){try{noteShareAuthChanged();}catch(_){}}
        if(!user){clearAdoptedUid();syncInitialized=false;Sync.renderAccount();return;}
        /* Login transition (user 2026-09-11): adopt-vs-upload runs once per uid.
           Same-uid resumes (reload/online/visibility) skip it — the adopted
           marker proves the transition already settled. */
        const SYNCING_TEXT='Syncing\u2026';
        Sync.setAccountStatus(SYNCING_TEXT);
        try{
          if(getAdoptedUid()===uid){await Sync.syncCycle();Sync.setAccountStatus('');syncInitialized=true;}
          else{
            const settled=await adoptOrUploadOnSignIn(user);
            if(settled){setAdoptedUid(uid);syncInitialized=true;}
            /* adoptOrUploadOnSignIn sets its own final status on every settled
               or error path; only clear here when it returned silently
               (offline/unreachable), so 'Syncing…' doesn't linger. */
            const statusEl=$('#accountStatus');
            if(statusEl&&statusEl.textContent===SYNCING_TEXT)Sync.setAccountStatus('');
            /* #649: an unsettled transition (offline / fetch error / dialog
               unavailable) leaves syncInitialized FALSE and the adopted
               marker unset, so the next resume for this same uid retries the
               transition instead of taking the same-uid early return above
               and silently merging. syncInitialized means "the login
               transition for the current uid settled" — nothing less. */
          }
          /* #512: flush subscription prefs to EmailOctopus now that the
             verified session email is known — prefs set while signed out
             (e.g. the onboarding checkbox) sync on first sign-in. Debounced
             and hash-guarded in email-sync.js; no-op when unchanged. */
          try{if(typeof queueEmailSync==='function')queueEmailSync();}catch(_){}
          /* (user 2026-09-14): after sign-in from the "Ready?" hero the Home
             view kept showing the signed-out state until a manual refresh —
             the account panel re-rendered but the view never did. Re-render
             the visible view once the transition settles so adopted cloud
             data appears immediately. Draft-safe: rerenderCurrentView skips
             the full re-render while a draft is open. */
          try{Sync.rerenderCurrentView();}catch(_){}
        }catch(err){Sync.showSyncError(err);}
        Sync.renderAccount();
      }
      /* ===== resume / init ===== */
      async function resumeSync(){
        /* #70: capture before Supabase init — on success the client strips
           ?code= from the URL, so a lingering code plus no session afterwards
           means the link failed (expired, already used, or opened in a
           different browser: PKCE links only work where they were requested).
           getSession() awaits init, so the exchange has settled by the check. */
        const hadAuthCode=/[?&]code=/.test(location.search);
        const hashErr=Sync.authCallbackErrorText();
        const sb=await Sync.getSupabase();
        if(!sb){
          if(hashErr||hadAuthCode)Sync.showAuthRecovery((hashErr||'That sign-in link didn\u2019t work.')+' No network connection \u2014 reconnect and try again.');
          /* PPL fix batch (2026-10-28, B9e): name the failure that
             actually happened. The old line printed "offline" for ANY
             cause — including a blocked/unreachable sync CDN on a
             device that was otherwise online. Offline is claimed only
             when the browser itself reports offline; a client-load
             failure says so; anything else stays generic. */
          else if(typeof navigator!=='undefined'&&navigator&&navigator.onLine===false)Sync.setAccountStatus('Sync unavailable offline \u2014 your data stays on this device.',true);
          else if(typeof Sync.supabaseFailure==='function'&&Sync.supabaseFailure()==='load')Sync.setAccountStatus('Sync unavailable \u2014 couldn\u2019t load the sync library. Your data stays on this device.',true);
          else Sync.setAccountStatus('Sync unavailable \u2014 your data stays on this device.',true);
          return;
        }
        let sessionUser=null;
        try{
          if(!authListenerAttached){
            authListenerAttached=true;
            sb.auth.onAuthStateChange((_event,s)=>{handleAuthChange(s).catch(()=>{});});
          }
          const {data}=await sb.auth.getSession();
          const session=data&&data.session?data.session:null;
          sessionUser=session?session.user:null;
          await handleAuthChange(session);
          if(!session&&(hadAuthCode||hashErr)){
            Sync.showAuthRecovery((hashErr||'That sign-in link didn\u2019t work \u2014 it may have expired, already been used, or been opened in a different browser.')+' Enter the code from the email below, or tap \u2018Email me a code\u2019 for a fresh one.');
          }
          /* Startup / back-online catch-up for an already-signed-in user:
             handleAuthChange no-ops for the same uid, so run a cycle explicitly. */
          if(session&&syncInitialized){
            Sync.setAccountStatus('Syncing\u2026');
            await Sync.syncCycle();
            Sync.setAccountStatus('');
          }
        }catch(_){/* stay local-only */}
        /* #506 follow-up (user 2026-09-16): a brand-new account created after
           boot gets the first-run onboarding flow (the boot gate only runs at
           load). maybeStartPostSignupOnboarding no-ops unless the account is
           genuinely new, the profile is data-free, and the flow never
           completed — the in-flow sign-in path is already up (of-active) so
           it skips there. */
        try{
          let freshAccount=false;
          try{
            /* #655: this probe read a bare `user` that does not exist in
               this scope — the ReferenceError was swallowed by the catch
               below and the fresh-account check never fired. The session
               user captured above is the intended source. */
            const createdAt=Date.parse(sessionUser&&sessionUser.created_at);
            freshAccount=Number.isFinite(createdAt)&&(Date.now()-createdAt)<60*1000;
          }catch(_){/* freshAccount stays false */}
          if(freshAccount&&typeof maybeStartPostSignupOnboarding==='function'){
            await maybeStartPostSignupOnboarding(true);
          }
        }catch(_){/* never break auth on an onboarding edge */}
        Sync.renderAccount();
      }
      /* Boots sync: wires and renders the account UI, resumes on online/visible. */
      function initSync(){
        Sync.wireAccountUI();
        Sync.renderAccount();
        /* 'online' re-arms the CDN import (getSupabase caches failures) and resumes. */
        window.addEventListener('online',()=>{Sync.resetSupabaseUnavailable();resumeSync().catch(()=>{});});
        /* A tab that was hidden/suspended may have missed its debounced push
           (background timers don't fire reliably) — catch up when visible again.
           B9e (2026-10-28): a foreground return also re-arms a failed CDN
           import (when the browser reports online), so the load-failure
           status can actually clear without waiting for an 'online' event. */
        document.addEventListener('visibilitychange',()=>{if(!document.hidden){if(typeof navigator==='undefined'||!navigator||navigator.onLine!==false)Sync.resetSupabaseUnavailable();resumeSync().catch(()=>{});}});
        resumeSync().catch(()=>{});
      }

      Sync.waitForLoginSettled=waitForLoginSettled;
      Sync.sendSignInLink=sendSignInLink;
      Sync.verifySignInCode=verifySignInCode;
      Sync.requestSignInCode=requestSignInCode;
      Sync.confirmSignInCode=confirmSignInCode;
      Sync.saveDisplayName=saveDisplayName;
      Sync.saveAccountEmail=saveAccountEmail; /* #423 */
      Sync.isValidEmailAddress=isValidEmailAddress; /* #423: unit-test hook */
      Sync.accountSubstance=accountSubstance; /* #424: unit-test hook */
      Sync.recommendSignInChoice=recommendSignInChoice; /* #424: unit-test hook */
      Sync.signInValueHasUserData=signInValueHasUserData; /* #450: unit-test hook */
      Sync.signInLocalHasData=signInLocalHasData; /* #450: unit-test hook */
      Sync.signOutAccount=signOutAccount;
      Sync.syncNowManual=syncNowManual;
      Sync.handleAuthChange=handleAuthChange;
      Sync.initSync=initSync;
    })();
    /* `lastAuthUid` stays a real global because share.js reads it; it
       mirrors Sync.lastAuthUid. (The bare initSync() forwarding shim was
       removed in the v1.912 #99 cleanup — boot calls Sync.initSync().) */
